using System.Text.Json.Serialization;

namespace TicketClassifier.Models;

public class TrainingMetrics
{
    public double MicroAccuracy { get; set; }
    public double MacroAccuracy { get; set; }
    public double LogLoss { get; set; }
    public double LogLossReduction { get; set; }

    [JsonIgnore]
    public bool HasInvalidValues =>
        double.IsNaN(LogLossReduction) || double.IsInfinity(LogLossReduction);

    /// <summary>
    /// Replaces NaN/Infinity values with 0 so the object can be serialized to JSON.
    /// </summary>
    public static TrainingMetrics Sanitize(TrainingMetrics m) => new()
    {
        MicroAccuracy = Clamp(m.MicroAccuracy),
        MacroAccuracy = Clamp(m.MacroAccuracy),
        LogLoss = Clamp(m.LogLoss),
        LogLossReduction = Clamp(m.LogLossReduction)
    };

    private static double Clamp(double v) =>
        double.IsNaN(v) || double.IsInfinity(v) ? 0.0 : v;
}

