7. {
8.     private readonly string _dataPath;
9.     private readonly string _modelPath;
10.     private readonly ILogger<ModelTrainingService> _logger;
11. 
12.     public ModelTrainingService(ILogger<ModelTrainingService> logger)
13.     {
14.         _dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "tickets.csv");
15.         _modelPath = Path.Combine(AppContext.BaseDirectory, "Data", "model.zip");
16.         _logger = logger;
17.     }
18. 
19.     public TrainingMetrics TrainAndEvaluate()
20.     {
21.         var mlContext = new MLContext(seed: 42);
22. 
23.         var data = mlContext.Data.LoadFromTextFile<TicketInput>(
24.             _dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);
25. 
26.         var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.2);
27. 
28.         var pipeline = mlContext.Transforms.Text
29.                 .FeaturizeText("SubjectFeatures", nameof(TicketInput.Subject))
30.             .Append(mlContext.Transforms.Text
31.                 .FeaturizeText("DescriptionFeatures", nameof(TicketInput.Description)))
32.             .Append(mlContext.Transforms.Concatenate("Features",
33.                 "SubjectFeatures", "DescriptionFeatures", nameof(TicketInput.Priority)))
34.             .Append(mlContext.Transforms.Conversion
35.                 .MapValueToKey("Label", nameof(TicketInput.Category)))
36.             .Append(mlContext.MulticlassClassification.Trainers
37.                 .SdcaMaximumEntropy("Label", "Features"))
38.             .Append(mlContext.Transforms.Conversion
39.                 .MapKeyToValue("PredictedLabel"));
40. 
41.         _logger.LogInformation("Training model with data from {Path}", _dataPath);
42.         var model = pipeline.Fit(split.TrainSet);
43. 
44.         var predictions = model.Transform(split.TestSet);
45.         var metrics = mlContext.MulticlassClassification.Evaluate(predictions);
46. 
47.         var result = new TrainingMetrics
48.         {
49.             MicroAccuracy = metrics.MicroAccuracy,
50.             MacroAccuracy = metrics.MacroAccuracy,
51.             LogLoss = metrics.LogLoss,
52.             LogLossReduction = metrics.LogLossReduction
53.         };
54. 
55.         _logger.LogInformation(
56.             "Model metrics — MicroAccuracy: {Micro:F4}, MacroAccuracy: {Macro:F4}, LogLoss: {LogLoss:F4}",
57.             result.MicroAccuracy, result.MacroAccuracy, result.LogLoss);
58. 
59.         mlContext.Model.Save(model, data.Schema, _modelPath);
60.         _logger.LogInformation("Model saved to {Path}", _modelPath);
